// route group: authenticator, then a guard that requires the principal
app.grouped(UserAuthenticator())
   .grouped(User.guardMiddleware())
   .get("orders") { req async throws -> [Order] in
       let user = try req.auth.require(User.self)
       guard user.can("orders:read") else { throw Abort(.forbidden) }
       return try await Order.query(on: req.db).all()
   }
